from pptx import Presentation
prs = Presentation('CVPR2025_FreeViewpoint_Human_Animation_Slides.pptx')
for i, slide in enumerate(prs.slides, 1):
    texts = []
    for shape in slide.shapes:
        if shape.has_text_frame:
            for para in shape.text_frame.paragraphs:
                t = para.text.strip()
                if t:
                    texts.append(t)
    # Get first meaningful text as title indicator
    title = texts[0] if texts else '(no text)'
    print(f'Slide {i:2d}: {title[:80]}')
print(f'\nTotal: {len(prs.slides)} slides')
print(f'Slide width: {prs.slide_width}')
print(f'Slide height: {prs.slide_height}')
